-- C.A.R.R.S demo data. Run AFTER schema.sql. Dates are relative to today, so there are always
-- payments that are due today, overdue, and in the future.
USE carrs;
SET SQL_SAFE_UPDATES = 0;








-- ===== tidy-ups so the sample data obeys the same rules as the program =====
-- the person who recorded a payment never verifies it (the MP verifies those instead)
UPDATE payment SET verified_by = 4 WHERE verified = TRUE AND verified_by = recorded_by;
UPDATE payment_audit a JOIN payment p ON p.payment_id = a.payment_id
    SET a.performed_by = p.verified_by WHERE a.action = 'VERIFIED';
UPDATE payment_change c JOIN payment p ON p.payment_id = c.payment_id
    SET c.changed_by = p.verified_by WHERE c.field_name = 'verified';
-- show the real scheduled date in the audit text
UPDATE payment_audit a JOIN payment p ON p.payment_id = a.payment_id
    SET a.details = REPLACE(a.details, 'its scheduled date', p.scheduled_date)
WHERE a.action = 'RECORDED';


-- ===== Appeals and Disputes: applications with decisions (ages vary: some inside, some past the 30-day window) =====
-- Approved applications cannot be appealed, a few already carry an appeal
UPDATE application SET locked = TRUE WHERE application_id = 5;
